const beforeConsolidation=render;render=function(){if(location.hash==='#consolidation'){document.getElementById('app').innerHTML=integratedShell('consolidation',heading('Program consolidation','Scholarion Academy · Build scope approved � Publication pending')+'<section class="card prose" id="consolidation-data" aria-live="polite">Loading catalog comparison…</section>',model.role);bind();fetch('data/consolidation.json').then(r=>{if(!r.ok)throw Error('Catalog comparison unavailable');return r.json();}).then(d=>{const node=document.getElementById('consolidation-data');if(!node)return;node.innerHTML=`<p>${esc(d.cohortDecision)}</p><p>No automatic credit, publication, merger or retirement. Lead faculty: ${esc(d.leadFaculty)}.</p><h2>Blocking gaps</h2><ul>${d.blockers.map(b=>`<li>${esc(b)}</li>`).join('')}</ul><label>Find a program<input id="consolidation-search" type="search" placeholder="Program number or title"></label><div class="table-scroll"><table><thead><tr><th>Program</th><th>Duration</th><th>Shared modules</th><th>Relationships</th><th>Decision</th></tr></thead><tbody>${d.programs.map(p=>`<tr data-consolidation-row><td>#${p.id} ${p.catalogPresent?`<a href="#program/${p.id}">${esc(p.title)}</a>`:esc(p.title)}</td><td>${esc(p.length)}</td><td>${p.moduleIds.map(id=>esc(d.modules.find(m=>m.id===id).title)).join('; ')}</td><td>${p.relationships.map(r=>`#${r.from} → #${r.to}: ${esc(r.detail)}`).join('<br>')||'None specified'}</td><td>${esc(p.decision)}<p>${esc(p.overlap)}</p></td></tr>`).join('')}</tbody></table></div><h2>Commons module index</h2><p>${esc(d.versionRule)}</p>${d.modules.map(m=>`<details><summary>${esc(m.title)} · ${esc(m.version)}</summary><p>Programs: ${m.programs.join(', ')}</p><p>Mapping only; learning content and assessments require faculty review.</p></details>`).join('')}`;}).catch(e=>{const n=document.getElementById('consolidation-data');if(n)n.textContent=e.message;});}else beforeConsolidation();const nav=document.querySelector('aside nav')||document.querySelector('aside');if(nav&&!nav.querySelector('[href="#consolidation"]'))nav.insertAdjacentHTML('beforeend','<a href="#consolidation">Program consolidation</a>');};
document.addEventListener('input',e=>{if(e.target.id==='consolidation-search')document.querySelectorAll('[data-consolidation-row]').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(e.target.value.toLowerCase()));});render();
